fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("vector is hex"))
        .collect()
}

#[test]
fn every_published_vector_derives_its_key() {
    let mut failures = Vec::new();
    for (i, (msg, ekey, expected)) in VECTORS.iter().enumerate() {
        let msg: [u8; KEY_MESSAGE_LEN] = unhex(msg).try_into().expect("164-byte key message");
        let ekey: [u8; EKEY_LEN] = unhex(ekey).try_into().expect("72-byte ekey");
        let got = decrypt_key(&msg, &ekey);
        if hex(&got) != *expected {
            failures.push(format!("  vector {i}: got {} want {expected}", hex(&got)));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} vectors failed:\n{}",
        failures.len(),
        VECTORS.len(),
        failures.join("\n")
    );
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn all_four_modes_are_covered() {
    // The mode byte at offset 12 selects one of four reply tables and one of four
    // message keys, and each takes a different path through the message decrypt.
    let mut seen = [false; 4];
    for (msg, _, _) in &VECTORS {
        let mode = usize::from(unhex(msg)[12]);
        assert!(mode < 4, "mode {mode} is out of range");
        seen[mode] = true;
    }
    assert!(seen.iter().all(|&s| s), "modes covered: {seen:?}");
}
